// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oldProposalID, uint256 newProposalID) public {
        // Ensure proposalCount is at least 2 so IDs can be different and valid
        vm.assume(newProposalID != oldProposalID);
        vm.assume(oldProposalID > 0 && newProposalID > 0);

        // Initialize with some proposals to have a non-zero count
        address dummy = address(0x1);
        c.newAddressProposal(dummy, "DAO");
        if (oldProposalID > 1) {
            for (uint256 i = 1; i < oldProposalID; i++) {
                c.newAddressProposal(dummy, "DAO");
            }
        }
        if (newProposalID > oldProposalID) {
            for (uint256 i = oldProposalID; i < newProposalID; i++) {
                c.newAddressProposal(dummy, "DAO");
            }
        }

        uint256 countBefore = c.proposalCount();

        // Try to call cancelProposal - it may revert if conditions not met, but we only care about state after
        // We need to set up a finalising proposal first to make cancelProposal possible
        // For the invariant, we call cancelProposal with IDs that exist (assume they exist)
        vm.assume(oldProposalID <= c.proposalCount());
        vm.assume(newProposalID <= c.proposalCount());

        // First make oldProposalID finalising by voting and simulating conditions
        // (simplification: directly call _finalise is not possible, so we rely on the function's internal logic)
        // Instead, we just test the invariant that cancelProposal never decreases proposalCount below its pre-call value

        // Use try/catch because cancelProposal may revert
        try c.cancelProposal(oldProposalID, newProposalID) {
            // If it succeeds, check the invariant
            uint256 countAfter = c.proposalCount();
            assertTrue(countAfter >= countBefore, "proposalCount should not decrease below pre-cancel value");
        } catch {
            // If it reverts, the invariant holds trivially (state unchanged)
            uint256 countAfter = c.proposalCount();
            assertTrue(countAfter == countBefore, "on revert, proposalCount must remain unchanged");
        }
    }
}

