        c.newGrantProposal(address(0x5678), 200);

        // Get total weight and vote to meet the conditions for cancelProposal
        // We need: oldProposal finalising, newProposal has minority, same type
        // First vote on proposal1 to make it have minority (but not majority) and then finalise it
        vm.assume(_seed % 100 < 50); // ensure we don't hit edge cases

        c.voteProposal(1);
        c.voteProposal(2);

        // Make proposal1 finalising by voting enough to trigger _finalise
        // Since both are GRANT type, hasMajority doesn't auto-finalise, but we can
        // directly call the internal path via voteProposal if quorum
        // Actually let's just ensure proposal2 has minority (votes > totalWeight/6)
        // by making totalWeight small enough

