pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address vader, address usdv, address vault, address recipient, uint amount, address proposedAddress, string memory typeStr, uint proposalID) public {
        // Bound parameters to valid ranges
        vm.assume(vader != address(0) && usdv != address(0) && vault != address(0));
        vm.assume(amount > 0 && amount <= type(uint256).max);
        vm.assume(proposedAddress != address(0));
        vm.assume(bytes(typeStr).length > 0 && bytes(typeStr).length <= 32);

        // Initialize contract
        c.init(vader, usdv, vault);

        // Create a proposal (grant or address type)
        if (keccak256(bytes(typeStr)) == keccak256(bytes("GRANT"))) {
            c.newGrantProposal(recipient, amount);
        } else {
            c.newAddressProposal(proposedAddress, typeStr);
        }

        // Record USDV before cancelProposal
        address usdvBefore = c.USDV();

        // Call cancelProposal with random IDs (we only check the effect on USDV)
        // If proposal doesn't exist or conditions fail, the call will revert, but we still check after
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancelProposal(uint256,uint256)", proposalID, proposalID + 1));

        // Assert USDV unchanged regardless of success/failure
        assertTrue(c.USDV() == usdvBefore, "USDV should remain unchanged after cancelProposal");
    }
}

