pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address vader, address usdv, address vault, address recipient, uint256 amount, address voter, string memory typeStr, uint256 coolOff) public {
        // Bound to avoid overflow/underflow
        vm.assume(vader != address(0) && usdv != address(0) && vault != address(0));
        vm.assume(voter != address(0));
        vm.assume(coolOff <= 100); // reasonable cool off period
        vm.assume(amount < 1e30); // avoid overflow in other state

        // Initialize
        c.init(vader, usdv, vault);

        // Create a grant proposal
        c.newGrantProposal(recipient, amount);
        uint256 proposalID = 1;

        // To make proposal finalising, we need to vote to reach quorum (need totalWeight > 0)
        // Since totalWeight depends on vault, we simulate by using vm.mockCall on vault totalWeight
        // But here we can just call voteProposal and rely on the logic
        // For simplicity, assume we can bypass quorum check by mocking vault
        // However, we can just set up the state: vote to get proposal finalising

        // Simulate vault returning weights
        // We'll prank as voter and call voteProposal which will call countMemberVotes
        // The vault's getMemberWeight may return 0, but we can mock it
        vm.mockCall(
            vault,
            abi.encodeWithSignature("getMemberWeight(address)", voter),
            abi.encode(100)
        );
        vm.mockCall(
            vault,
            abi.encodeWithSignature("totalWeight()"),
            abi.encode(1000)
        );

        vm.prank(voter);
        c.voteProposal(proposalID);

        // Now proposal should be finalising
        // Create a new proposal of same type to cancel
        c.newGrantProposal(recipient, amount);
        uint256 newProposalID = 2;

        // Vote on new proposal to have minority (need > 1000/6 = 166, so need votes > 166)
        // We can make voter vote again with weight 200
        vm.mockCall(
            vault,
            abi.encodeWithSignature("getMemberWeight(address)", voter),
            abi.encode(200)
        );
        vm.prank(voter);
        c.voteProposal(newProposalID);

        // Now cancel the old proposal with new proposal
        address usdvBefore = c.USDV();
        c.cancelProposal(proposalID, newProposalID);
        address usdvAfter = c.USDV();

        assertTrue(usdvAfter == usdvBefore, "USDV should not change after cancelProposal");
    }
}

