            c.newAddressProposal(proposedAddress, typeStr);
        } else {
            c.newGrantProposal(recipient, amount);
        }
        uint256 oldPID = c.proposalCount();

        // Create a new proposal of the same type (to satisfy cancelProposal requirement)
        vm.prank(proposer);
        if (c.mapPID_type(oldPID).length > 5) {
            c.newAddressProposal(proposedAddress, typeStr);
        } else {
            c.newGrantProposal(recipient, amount);
        }
