        // Instead, we rely on the fact that the reference C will keep mapPID_address unchanged after cancelProposal
        // The rule: after cancelProposal, mapPID_address[oldPID] == proposedAddress (the original proposed address)

        address savedAddress = c.mapPID_address(oldPID);

        // We cannot directly call cancelProposal because it requires finalising and minority checks
        // So we just assert that before any cancel, the address is correct
