pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oldPID, uint256 newPID, address recipient, uint256 amount, uint256 timeJump) public {
        // Avoid zero proposal IDs (c's first proposal is 1)
        vm.assume(oldPID > 0 && oldPID <= 10);
        vm.assume(newPID > 0 && newPID <= 10);
        vm.assume(oldPID != newPID);
        vm.assume(recipient != address(0));
        vm.assume(amount > 0 && amount <= 1e30);
        vm.assume(timeJump > 0 && timeJump <= 100000);

        // Create a grant proposal for oldPID
        for (uint256 i = 1; i <= oldPID; i++) {
            c.newGrantProposal(recipient, amount);
        }

        // First vote to have finalising start
        vm.prank(address(0x1));
        c.voteProposal(oldPID);

        // Record the timestamp before cancelProposal
        uint256 timeBeforeCancel = block.timestamp;

        // Warp to a later time to ensure time difference
        vm.warp(block.timestamp + timeJump);

        // Create a second proposal for newPID
        for (uint256 i = oldPID + 1; i <= newPID; i++) {
            c.newGrantProposal(recipient, amount);
        }

        // Record timeStart before cancel
        uint256 timeStartBefore = c.mapPID_timeStart(oldPID);

        // Attempt to cancel - will revert if conditions not met
        try c.cancelProposal(oldPID, newPID) {
            // If cancel succeeds, timeStart should be unchanged (the bug sets it to block.timestamp before finalising)
            // In the reference, cancel doesn't change timeStart, so it stays as the original finalising time
            // In the mutant, cancel may have set timeStart to block.timestamp earlier than the cancel block.timestamp
            uint256 timeStartAfter = c.mapPID_timeStart(oldPID);
            // The cancelled proposal should NOT have timeStart moved forward to the cancel time
            // It should still be the original finalising time (which is < timeBeforeCancel)
            assertTrue(timeStartAfter <= timeBeforeCancel, "timeStart should not exceed the original finalising time");
        } catch {
            // If cancel reverts, no state change, so no assertion needed
            assertTrue(true);
        }
    }
}
